    "Before you start": "Zanim zaczniesz",
    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "Kompresja wiąże się z ponownym kodowaniem wideo i może obniżyć jego jakość. Jeśli dany format nie obsługuje ścieżki audio, napisów lub danych, proces zostanie przerwany zamiast usuwać te elementy bez powiadomienia. Oryginalny plik pozostaje niezmieniony.",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "Ta przeglądarka nie może zapisać wyniku jako strumienia, więc tymczasowo wykorzysta pamięć urządzenia. Bardzo duże pliki wideo mogą przekroczyć możliwości przeglądarki lub urządzenia.",
    "Compress video": "Kompresuj wideo",
