    "This video could not be made smaller. No copy was saved; your original is unchanged. Try a lower quality or resolution.": "Nie udało się zmniejszyć rozmiaru tego wideo. Nie zapisano kopii; oryginał pozostaje niezmieniony. Spróbuj wybrać niższą jakość lub rozdzielczość.",
