    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG lub ICO. W przypadku plików animowanych eksportowana jest pierwsza klatka. Metadane nie są kopiowane.",
    "Transparent areas become white. Animated images use only their first frame.": "Przezroczyste obszary stają się białe. W przypadku animowanych obrazów wykorzystywana jest tylko pierwsza klatka.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG i ICO. Z plików animowanych eksportowana jest tylko pierwsza klatka. Rozdzielczość wyjściowa do 40 megapikseli.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Konwertuj popularne formaty obrazów na JPG, PNG lub WebP bezpośrednio na swoim urządzeniu. Maksymalnie 20 plików.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Dodaj do 20 obrazów. Brak sztywnego limitu rozmiaru pliku; limit 20 megapikseli na obraz. Przetwarzanie dużych partii zależy od pamięci urządzenia.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Obrazy zostały przekonwertowane. Pliki animowane zamieniane są na pojedynczą klatkę; metadane nie są kopiowane.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Niektóre pliki zostały pominięte. Użyj obsługiwanego formatu obrazu i przestrzegaj limitów określonych na stronie.",
    "This image could not be decoded by your browser. Try another file or browser.": "Ten obraz nie mógł zostać zdekodowany przez Twoją przeglądarkę. Spróbuj użyć innego pliku lub przeglądarki.",
    "Choose a supported image format.": "Wybierz obsługiwany format obrazu.",
    "The browser does not support the selected output format.": "Przeglądarka nie obsługuje wybranego formatu wyjściowego.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Do 20 obrazów · 20 megapikseli na obraz · brak sztywnego limitu rozmiaru pliku. Przetwarzanie dużych partii zależy od pamięci urządzenia.",
    "Choose up to 20 images.": "Wybierz maksymalnie 20 obrazów.",
    "AVIF and some HEIC files may depend on browser support.": "Obsługa plików AVIF i niektórych plików HEIC zależy od przeglądarki.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Obsługa plików wejściowych AVIF i niektórych HEIC zależy od przeglądarki. Animowane pliki GIF, APNG i WebP są zamieniane na statyczny obraz. Pliki SVG są rasteryzowane, a nie konwertowane na edytowalną grafikę wektorową. Metadane nie są kopiowane.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "W przypadku wielostronicowych plików TIFF przetwarzana jest tylko pierwsza strona. Niektóre warianty kompresji TIFF mogą nie zostać poprawnie odczytane.",
    "Choose a DOCX, XLSX or PPTX file": "Wybierz plik DOCX, XLSX lub PPTX",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Pliki pozostają na Twoim urządzeniu. Limity: 100 MB dla pliku wejściowego, 200 MB dla rozpakowanych danych i 5000 elementów pakietu.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Ta funkcja bezpiecznie ponownie kompresuje pakiet Office bez modyfikowania jego zawartości. Osadzone zdjęcia nie są ponownie kompresowane, więc wynikowy plik może nie być mniejszy. Obsługa nie obejmuje plików podpisanych, zaszyfrowanych, zawierających makra ani plików w starszych formatach Office. Zachowaj oryginał.",
    "Try to reduce file size": "Spróbuj zmniejszyć rozmiar pliku",
    "Processing runs locally in this browser. No upload.": "Przetwarzanie odbywa się lokalnie w przeglądarce. Plik nie jest przesyłany na serwer.",
    "Recompressing the Office package on your device…": "Ponowna kompresja pakietu Office na urządzeniu…",
    "This package is already compact. No smaller download was created.": "Ten pakiet jest już zoptymalizowany. Nie utworzono mniejszego pliku do pobrania.",
    "A smaller copy is ready. Compare it and keep your original.": "Mniejsza kopia jest gotowa. Porównaj ją z oryginałem i zachowaj oryginał.",
    "The file could not be safely recompressed. Your original has not changed.": "Nie udało się bezpiecznie ponownie skompresować pliku. Oryginał pozostał bez zmian.",
    "Processing canceled. Your original file is unchanged.": "Przetwarzanie anulowane. Oryginalny plik pozostał bez zmian.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Wybierz nowoczesny plik DOCX, XLSX lub PPTX.",
    "This file is larger than the 100 MB local processing limit.": "Plik przekracza limit 100 MB dla przetwarzania lokalnego.",
    "The expanded package exceeds the 200 MB local processing limit.": "Rozpakowany pakiet przekracza limit 200 MB dla przetwarzania lokalnego.",
    "Encrypted Office packages are not supported.": "Pakiety Office chronione szyfrowaniem nie są obsługiwane.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "Pliki Office podpisane cyfrowo lub zawierające makra nie są obsługiwane, aby uniknąć unieważnienia podpisów lub makr.",
    "The selected file is not a valid modern Office document of that type.": "Wybrany plik nie jest poprawnym, nowoczesnym dokumentem pakietu Office tego typu.",
    "Choose an audio file": "Wybierz plik audio",
    "Compress audio": "Kompresuj dźwięk",
