    "Audio compression: {percent}%": "Kompresja dźwięku: {percent}%",
    "Done. The compressed copy is {size} smaller. Check the sound; your original is unchanged.": "Gotowe. Skompresowana kopia jest o {size} mniejsza. Sprawdź dźwięk; plik oryginalny pozostał bez zmian.",
    "No smaller audio copy was created. Your original is unchanged.": "Nie utworzono mniejszej kopii dźwięku. Plik oryginalny pozostał bez zmian.",
    "Processing canceled. Your original is unchanged.": "Przetwarzanie anulowane. Plik oryginalny pozostał bez zmian.",
    "Saving canceled. Your original is unchanged.": "Zapisywanie anulowane. Plik oryginalny pozostał bez zmian.",
    "Checking for audio…": "Wyszukiwanie dźwięku…",
    "Downloading speech model (first use is about 43 MB)…": "Pobieranie modelu mowy (pierwsze użycie wymaga pobrania ok. 43 MB)…",
    "Downloading model: {percent}%": "Pobieranie modelu: {percent}%",
    "Transcribing on your device…": "Transkrypcja na urządzeniu…",
    "Transcription complete. Review names and numbers.": "Transkrypcja zakończona. Sprawdź nazwiska i liczby.",
    "No speech detected. Try clearer audio or choose a language.": "Nie wykryto mowy. Spróbuj użyć wyraźniejszego nagrania lub wybierz język.",
    "Copied to clipboard.": "Skopiowano do schowka.",
    "Copy was blocked. Select the text and copy it manually.": "Kopiowanie zablokowane. Zaznacz tekst i skopiuj go ręcznie.",
    "Text file downloaded.": "Pobrano plik tekstowy.",
    "This file or codec could not be processed. Try another supported format.": "Nie udało się przetworzyć tego pliku lub kodeka. Spróbuj użyć innego obsługiwanego formatu.",
    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "W przypadku długich nagrań lub plików o wysokiej rozdzielczości zaleca się korzystanie z komputera stacjonarnego lub laptopa. Pozostaw tę kartę otwartą; szybkość działania, zużycie pamięci i baterii zależą od Twojego urządzenia.",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "Ponowne kodowanie może obniżyć jakość dźwięku lub zwiększyć rozmiar pliku. Oryginalny plik pozostanie niezmieniony.",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "Przy pierwszym użyciu pobierane jest około 58 MB danych modelu i lokalnego silnika. Twoje nagranie nie jest przesyłane na serwer; przeglądarka może pobrać te dane ponownie po wyczyszczeniu pamięci podręcznej.",
    "Your file is processed locally and is not uploaded.": "Plik jest przetwarzany lokalnie i nie jest przesyłany na serwer.",
