    "PDF files stay on this device. Choose up to 10 files.": "Pliki PDF pozostają na tym urządzeniu. Wybierz maksymalnie 10 plików.",
    "Page ranges (for example: 1-3, 5-7)": "Zakresy stron (np. 1-3, 5-7)",
