    "Pages become images. Text will not be selectable and links, forms and signatures are not kept. The new file can be larger than the original.": "Strony zostaną przekształcone w obrazy. Tekst nie będzie możliwy do zaznaczenia, a linki, formularze i podpisy nie zostaną zachowane. Nowy plik może być większy od oryginału.",
