    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Pliki pakietu Office pozostają na Twoim urządzeniu. Układ, formuły, wykresy, animacje, czcionki i podziały stron mogą ulec zmianie. Konwersja Office do PDF otwiera okno drukowania w przeglądarce. W przypadku dużych plików zaleca się użycie komputera.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "Konwersja PDF do Excela szacuje liczbę wierszy na podstawie zaznaczonego tekstu; nie odtwarza formuł ani tabel. Konwersja PDF do PowerPointa tworzy slajdy zawierające wyłącznie obrazy. Skanowane pliki PDF wymagają wcześniejszego przetworzenia OCR.",
