      "intro": "Usuwanie duplikatów wierszy jest proste; kluczowe znaczenie ma jednak ustalenie, co dokładnie uznajemy za „duplikat”. Powtarzający się adres e-mail, powtarzający się cały wiersz oraz powtarzająca się kombinacja imienia i nazwiska z datą to różne przypadki. Skonfiguruj odpowiednią regułę i zabezpiecz oryginał przed usunięciem jakichkolwiek danych.",
