              "text": "Jeśli wymagana jest zgodność wszystkich komórek w dwóch wierszach, porównaj całe wiersze. Jeśli rekord jest jednoznacznie identyfikowany przez identyfikator klienta, porównaj tę kolumnę. Możesz również użyć kombinacji danych — na przykład imienia i nazwiska — jeśli tego właśnie wymaga Twoje zadanie."
